[{'id': 454441, 'question': 'The Hobbit >> part of the series', 'answer': 'South Park', 'paragraph_support_idx': 0, 'support_paragraph': {'idx': 0, 'title': 'The Hobbit (South Park)', 'paragraph_text': '"The Hobbit" is the tenth and final episode in the seventeenth season of the American animated television series "South Park". The 247th episode of the series overall, it premiered on Comedy Central in the United States on December 11, 2013. The story centers upon Wendy Testaburger\'s attempts to raise awareness of media impact on body image, which leads to a crusade by rapper Kanye West to convince the world that his fiancée, Kim Kardashian, is not a hobbit. The episode received largely positive reviews from critics, who praised Wendy\'s story arc and the return of West.', 'is_supporting': True}}
 {'id': 55349, 'question': 'who does the voice of stan on #1', 'answer': 'Trey Parker', 'paragraph_support_idx': 7, 'support_paragraph': {'idx': 7, 'title': 'List of South Park cast members', 'paragraph_text': 'Trey Parker voices four of the main characters: Stan Marsh, Eric Cartman, Randy Marsh and Mr. Garrison. He also provides the voices of several recurring characters, such as Clyde Donovan, Mr. Hankey, Mr. Mackey, Stephen Stotch, Jimmy Valmer, Timmy Burch, Tuong Lu Kim and Phillip.', 'is_supporting': True}}
 {'id': 651302, 'question': '#2 >> place of birth', 'answer': 'Denver', 'paragraph_support_idx': 9, 'support_paragraph': {'idx': 9, 'title': 'Dian Bachar', 'paragraph_text': 'Dian Bachar (; born October 26, 1970 in Denver, Colorado) is an American actor most notable for his roles in various films by or starring his friends Trey Parker and Matt Stone, such as "Cannibal! The Musical" (George Noon), "Orgazmo" (Ben Chapleski) and his most famous role as Kenny "Squeak" Scolari in 1998\'s "BASEketball", as well as making the occasional appearance on "South Park". He appeared as an alien engineer in "Galaxy Quest". Although the bulk of his scenes were cut, he can be seen on the DVD\'s "Special Features".', 'is_supporting': True}}]

[{'id': 105126, 'question': 'The country for Gado-gado was what?', 'answer': 'Indonesia', 'paragraph_support_idx': 13, 'support_paragraph': {'idx': 13, 'title': 'Gado-gado', 'paragraph_text': '"Gado-gado" is widely sold in almost every part of Indonesia, with each area having its own modifications. It is thought to have originally been a Sundanese dish, as it is most prevalent in Western parts of Java (which includes Jakarta, Banten, and West Java provinces). The Javanese have their own slightly similar version of a vegetables-in-peanut-sauce dish called "pecel" which is more prevalent in Central and East Java. "Gado-gado" is widely available from hawkers\' carts, stalls ("warung") and restaurants and hotels in Indonesia; it is also served in Indonesian-style restaurants worldwide. Though it is customarily called a salad, the peanut sauce is a larger component of "gado-gado" than is usual for the dressings in Western-style salads; the vegetables should be well coated with it.', 'is_supporting': True}}
 {'id': 443779, 'question': '#1 –Timor Leste Commission of Truth and Friendship >> country', 'answer': 'East Timor', 'paragraph_support_idx': 9, 'support_paragraph': {'idx': 9, 'title': 'Indonesia–Timor Leste Commission of Truth and Friendship', 'paragraph_text': 'The Indonesia–Timor Leste Commission on Truth and Friendship was a truth commission established jointly by the governments of Indonesia and East Timor in August 2005. The commission was officially created to investigate acts of violence that occurred around the independence referendum held in East Timor in 1999 and sought to find the "conclusive truth" behind the events. After holding private hearings and document reviews, the commission handed in the final report on July 15, 2008 to the presidents of both nations, and was fully endorsed by Indonesian President Susilo Bambang Yudhoyono, providing the first acknowledgement by the government of Indonesia of the human rights violations committed by state institutions in Timor. The commission is notable for being the first modern truth commission to be bilateral.', 'is_supporting': True}}
