[{'id': 836699, 'question': 'Nightshade >> platform', 'answer': 'Nintendo Entertainment System', 'paragraph_support_idx': 2, 'support_paragraph': {'idx': 2, 'title': 'Nightshade (1992 video game)', 'paragraph_text': 'Nightshade Part 1: The Claws of Sutekh is an action-adventure video game released in 1992 for the Nintendo Entertainment System. It was developed by Beam Software and published by Ultra Games. The game was meant to be the first part in a series, but no sequels were ever made; however, it served as the basis for Beam Software\'s 1993 game ""Shadowrun".', 'is_supporting': True}}
 {'id': 15840, 'question': 'What is the abbreviation of #1 ?', 'answer': 'NES', 'paragraph_support_idx': 17, 'support_paragraph': {'idx': 17, 'title': 'Nintendo Entertainment System', 'paragraph_text': 'The Nintendo Entertainment System (also abbreviated as NES) is an 8-bit home video game console that was developed and manufactured by Nintendo. It was initially released in Japan as the Family Computer (Japanese: ファミリーコンピュータ, Hepburn: Famirī Konpyūta?) (also known by the portmanteau abbreviation Famicom (ファミコン, Famikon?) and abbreviated as FC) on July 15, 1983, and was later released in North America during 1985, in Europe during 1986, and Australia in 1987. In South Korea, it was known as the Hyundai Comboy (현대 컴보이 Hyeondae Keomboi) and was distributed by SK Hynix which then was known as Hyundai Electronics. It was succeeded by the Super Nintendo Entertainment System.', 'is_supporting': True}}
 {'id': 36002, 'question': "What were the Genesis's advantages over the #2 ?", 'answer': 'built on 16-bit architectures and offered improved graphics and sound', 'paragraph_support_idx': 7, 'support_paragraph': {'idx': 7, 'title': 'Super Nintendo Entertainment System', 'paragraph_text': "To compete with the popular Family Computer in Japan, NEC Home Electronics launched the PC Engine in 1987, and Sega Enterprises followed suit with the Mega Drive in 1988. The two platforms were later launched in North America in 1989 as the TurboGrafx-16 and the Genesis respectively. Both systems were built on 16-bit architectures and offered improved graphics and sound over the 8-bit NES. However, it took several years for Sega's system to become successful. Nintendo executives were in no rush to design a new system, but they reconsidered when they began to see their dominance in the market slipping.", 'is_supporting': True}}]

